  // format backend response (keeps your original logic)
  function formatBackendResponse(data){
    var payload = Array.isArray(data) && data.length ? data[0] : data;
    if(!payload) return 'No data received.';
    function fmt(cur,next,reason){ return ['Replace your current variable:','"'+cur+'"','','with:','"'+next+'"','','Reason:', reason || 'No reason provided'].join('\n'); }
    if(payload.current_variable && payload.new_variable) return fmt(payload.current_variable, payload.new_variable, payload.reason);
    if(payload.formatted_output){
      var fo = payload.formatted_output;
      if(typeof fo === 'string'){
        try{ fo = JSON.parse(fo); }catch(e){ return fo; }
      }
      if(fo.current_variable && fo.new_variable) return fmt(fo.current_variable, fo.new_variable, fo.reason);
      return JSON.stringify(fo, null, 2);
    }
    if(typeof payload === 'object') return JSON.stringify(payload, null, 2);
    return String(payload);
  }

