    var sel = (shadow.querySelector('input[name="template"]:checked')||{}).value || null;
    if(!sel){ alert('Please select a template first.'); return; }
    if(!text || isLoading) return;
    var userMessage = { id: Date.now().toString(), text: text, sender: 'user', timestamp: new Date().toISOString() };
    messages.push(userMessage); saveMessages(); renderMessages();
